export const displayName = 'Mot de passe oublié';
export const screenSize = 'mobile';

import Icon from '@global/Icon';

export default function ForgotPassword() {
  return (
    <div className="bg-surface flex flex-col min-h-full">
      {/* Top Nav */}
      <div className="bg-background border-b border-border px-4 py-3 flex items-center">
        <button className="flex items-center gap-1.5 text-sm font-semibold text-foreground">
          <Icon i="arrow-left" size={18} /> {t('Retour à la connexion')}
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 px-4 py-8 flex flex-col items-center">

        {/* Icon */}
        <div className="w-20 h-20 bg-secondary rounded-full flex items-center justify-center mb-6">
          <Icon i="lock-keyhole" size={36} className="text-primary" />
        </div>

        {/* Title */}
        <h1 className="font-headings font-bold text-2xl text-foreground mb-2 text-center">
          {t('Mot de passe oublié ?')}
        </h1>
        <p className="text-sm text-muted-foreground text-center mb-8 px-2">
          {t('Entrez votre adresse email ci-dessous. Nous vous enverrons un lien pour réinitialiser votre mot de passe.')}
        </p>

        {/* Email Form Box */}
        <div className="w-full bg-card border-2 border-primary/20 rounded-xl p-5 mb-5">
          <label className="block text-xs font-bold text-muted-foreground uppercase mb-2">
            {t('Adresse email')}
          </label>
          <div className="border border-border rounded-lg px-3 py-3 bg-background flex items-center gap-2">
            <Icon i="mail" size={16} className="text-muted-foreground flex-shrink-0" />
            <p className="text-sm text-muted-foreground">{t('votre@email.com')}</p>
          </div>
        </div>

        {/* CTA */}
        <button
          className="w-full py-4 bg-primary text-primary-foreground font-bold text-base rounded-xl flex items-center justify-center gap-2 mb-4"
          style={{ boxShadow: '0 4px 16px rgba(242,101,34,0.35)' }}
        >
          <Icon i="send" size={18} />
          {t('Envoyer le lien de réinitialisation')}
        </button>

        <p className="text-xs text-muted-foreground text-center mb-8">
          {t('Vérifiez aussi votre dossier spam si vous ne recevez pas l\'email.')}
        </p>

        {/* Divider */}
        <div className="w-full flex items-center gap-3 mb-6">
          <div className="flex-1 h-px bg-border"></div>
          <span className="text-xs text-muted-foreground">{t('ou')}</span>
          <div className="flex-1 h-px bg-border"></div>
        </div>

        {/* Alternative Methods */}
        <div className="w-full bg-card border border-border rounded-xl p-4">
          <p className="text-xs font-bold text-muted-foreground uppercase mb-3">{t('Autres options')}</p>
          <div className="space-y-2">
            <button className="w-full flex items-center gap-3 text-sm text-foreground font-medium">
              <div className="w-8 h-8 bg-secondary rounded-lg flex items-center justify-center">
                <Icon i="shield" size={14} className="text-primary" />
              </div>
              {t('Via Google Authenticator')}
              <Icon i="chevron-right" size={14} className="text-muted-foreground ml-auto" />
            </button>
            <div className="border-t border-border"></div>
            <button className="w-full flex items-center gap-3 text-sm text-foreground font-medium">
              <div className="w-8 h-8 bg-secondary rounded-lg flex items-center justify-center">
                <Icon i="headset" size={14} className="text-primary" />
              </div>
              {t('Contacter le support')}
              <Icon i="chevron-right" size={14} className="text-muted-foreground ml-auto" />
            </button>
          </div>
        </div>

      </div>
    </div>
  );
}

export const displayName = 'Créer un compte (Mobile)';
export const screenSize = 'mobile';

import AppLogo from '@components/AppLogo';
import Icon from '@global/Icon';

const GoogleLogo = () => (
  <svg width="20" height="20" viewBox="0 0 48 48" className="flex-shrink-0">
    <path fill="#EA4335" d="M44.5 20H24v8.5h11.8C34.7 33.9 29.8 37 24 37c-7.2 0-13-5.8-13-13s5.8-13 13-13c3.1 0 5.9 1.1 8.1 2.9l6-6C34.6 5.1 29.6 3 24 3 12.4 3 3 12.4 3 24s9.4 21 21 21c10.5 0 20-7.9 20-21 0-1.4-.1-2.7-.5-4z"/>
    <path fill="#34A853" d="M6.3 14.7l7 5.1C15.1 16 19.2 13 24 13c3.1 0 5.9 1.1 8.1 2.9l6-6C34.6 5.1 29.6 3 24 3c-7.8 0-14.5 4.4-18.7 11.7z"/>
    <path fill="#FBBC05" d="M24 45c5.5 0 10.5-1.9 14.3-5.1l-6.6-5.4C29.6 35.9 26.9 37 24 37c-5.8 0-10.7-3.9-12.3-9.3l-7 5.4C8.5 41 15.8 45 24 45z"/>
    <path fill="#4285F4" d="M44.5 20H24v8.5h11.8c-1 3-3.2 5.5-6.2 7l6.6 5.4C40.6 37.3 44.5 31.3 44.5 24c0-1.4-.1-2.7-.5-4z"/>
  </svg>
);

export default function SignupPageMobile() {
  return (
    <div className="bg-background flex flex-col px-5 pt-12 pb-8">
      {/* Logo */}
      <div className="flex justify-center mb-8">
        <AppLogo size="md" />
      </div>

      <h1 className="font-headings font-bold text-2xl text-foreground mb-1">{t('Créer un compte')}</h1>
      <p className="text-sm text-muted-foreground mb-8">{t('Rejoignez Musika et créez votre première chanson')}</p>

      {/* Google Button */}
      <button className="w-full py-3.5 bg-white border border-border rounded-xl flex items-center justify-center gap-3 mb-6 font-semibold text-foreground text-sm"
        style={{ boxShadow: '0 1px 4px rgba(0,0,0,0.08)' }}>
        <GoogleLogo />
        {t('S\'inscrire avec Google')}
      </button>

      {/* Divider */}
      <div className="flex items-center gap-3 mb-6">
        <div className="flex-1 h-px bg-border"></div>
        <span className="text-xs text-muted-foreground font-medium">{t('OU')}</span>
        <div className="flex-1 h-px bg-border"></div>
      </div>

      {/* Email */}
      <div className="mb-4">
        <label className="text-xs font-bold text-muted-foreground uppercase block mb-2">{t('Adresse email')}</label>
        <div className="border border-border rounded-xl px-4 py-3.5 bg-input flex items-center gap-2">
          <Icon i="mail" size={17} className="text-muted-foreground flex-shrink-0" />
          <p className="text-sm text-muted-foreground flex-1">{t('votre@email.com')}</p>
        </div>
      </div>

      {/* Password */}
      <div className="mb-6">
        <label className="text-xs font-bold text-muted-foreground uppercase block mb-2">{t('Mot de passe')}</label>
        <div className="border border-border rounded-xl px-4 py-3.5 bg-input flex items-center gap-2">
          <Icon i="lock" size={17} className="text-muted-foreground flex-shrink-0" />
          <p className="text-sm text-muted-foreground flex-1">{t('••••••••')}</p>
          <button className="text-muted-foreground flex-shrink-0">
            <Icon i="eye-off" size={17} />
          </button>
        </div>
        <p className="text-xs text-muted-foreground mt-2">{t('Minimum 8 caractères avec majuscules et chiffres')}</p>
      </div>

      {/* Signup Button */}
      <button className="w-full py-4 bg-primary text-primary-foreground font-bold text-base rounded-xl mb-6"
        style={{ boxShadow: '0 4px 16px rgba(242,101,34,0.35)' }}>
        {t('Continuer')}
      </button>

      {/* Terms */}
      <p className="text-center text-xs text-muted-foreground mb-6">
        {t('En créant un compte, vous acceptez nos ')} <a className="text-primary font-semibold">{t('conditions d\'utilisation')}</a> {t('et notre ')} <a className="text-primary font-semibold">{t('politique de confidentialité')}</a>
      </p>

      {/* Login Link */}
      <p className="text-center text-sm text-muted-foreground">
        {t('Vous avez déjà un compte ? ')} <a className="text-primary font-semibold">{t('Se connecter')}</a>
      </p>
    </div>
  );
}

export const displayName = 'Vérification Double Facteur (2FA)';
export const screenSize = 'mobile';

import Icon from '@global/Icon';

export default function TwoFactorAuth() {
  return (
    <div className="bg-surface flex flex-col min-h-full">
      {/* Top Nav */}
      <div className="bg-background border-b border-border px-4 py-3 flex items-center">
        <button className="flex items-center gap-1.5 text-sm font-semibold text-foreground">
          <Icon i="arrow-left" size={18} /> {t('Retour')}
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 px-4 py-8 flex flex-col items-center">

        {/* Icon */}
        <div className="w-20 h-20 bg-secondary rounded-full flex items-center justify-center mb-6">
          <Icon i="shield-check" size={36} className="text-primary" />
        </div>

        {/* Title */}
        <h1 className="font-headings font-bold text-2xl text-foreground mb-2 text-center">
          {t('Vérification en deux étapes')}
        </h1>
        <p className="text-sm text-muted-foreground text-center mb-2">
          {t('Un code de vérification a été envoyé par email à')}
        </p>
        <p className="text-sm font-semibold text-foreground text-center mb-8">
          {t('jean@example.com')}
        </p>

        {/* Code Input Box */}
        <div className="w-full bg-card border-2 border-primary/20 rounded-xl p-6 mb-6">
          <label className="block text-xs font-bold text-muted-foreground uppercase mb-4 text-center">
            {t('Entrez le code à 6 chiffres')}
          </label>

          {/* 6 digit boxes */}
          <div className="flex gap-2 justify-center mb-4">
            {[0, 1, 2, 3, 4, 5].map((i) => (
              <div
                key={i}
                className={`w-12 h-14 border-2 rounded-xl flex items-center justify-center font-bold text-xl font-mono ${
                  i < 3
                    ? 'border-primary bg-secondary text-primary'
                    : i === 3
                    ? 'border-primary bg-background text-foreground'
                    : 'border-border bg-background text-muted-foreground'
                }`}
              >
                {i === 0 ? '4' : i === 1 ? '8' : i === 2 ? '3' : i === 3 ? '' : ''}
                {i === 3 && <span className="inline-block w-0.5 h-6 bg-primary animate-pulse ml-0.5"></span>}
              </div>
            ))}
          </div>

          <p className="text-xs text-muted-foreground text-center">
            {t('Le code expire dans')} <span className="font-bold text-foreground">{t('04:32')}</span>
          </p>
        </div>

        {/* Action Buttons */}
        <button
          className="w-full py-4 bg-primary text-primary-foreground font-bold text-base rounded-xl flex items-center justify-center gap-2 mb-3"
          style={{ boxShadow: '0 4px 16px rgba(242,101,34,0.35)' }}
        >
          <Icon i="shield-check" size={18} />
          {t('Vérifier')}
        </button>

        <button className="w-full py-3 border border-border text-foreground font-semibold text-sm rounded-xl bg-background mb-6">
          {t('Ne pas recevoir le code ?')}
        </button>

        {/* Resend + Switch method */}
        <div className="w-full space-y-3">
          <div className="flex items-center justify-center gap-2">
            <Icon i="refresh-cw" size={14} className="text-muted-foreground" />
            <button className="text-sm text-primary font-semibold">{t('Renvoyer le code')}</button>
          </div>

          <div className="bg-card border border-border rounded-xl p-4">
            <p className="text-xs font-bold text-muted-foreground uppercase mb-3">{t('Autres méthodes de vérification')}</p>
            <div className="space-y-2">
              <button className="w-full flex items-center gap-3 text-sm text-foreground font-medium">
                <div className="w-8 h-8 bg-secondary rounded-lg flex items-center justify-center">
                  <Icon i="mail" size={14} className="text-primary" />
                </div>
                {t('Envoyer par email')}
                <Icon i="chevron-right" size={14} className="text-muted-foreground ml-auto" />
              </button>
              <div className="border-t border-border"></div>
              <button className="w-full flex items-center gap-3 text-sm text-foreground font-medium">
                <div className="w-8 h-8 bg-secondary rounded-lg flex items-center justify-center">
                  <Icon i="shield" size={14} className="text-primary" />
                </div>
                {t('Google Authenticator')}
                <Icon i="chevron-right" size={14} className="text-muted-foreground ml-auto" />
              </button>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}

