@theme {
  /* used via utility-classes, bg-background, text-primary, and many more */
  --color-background: #FAFAF7;
  --color-foreground: #1A1A1A;
  --color-border: #E8E3DC;
  --color-input: #F3EFE9;
  --color-primary: #F26522;
  --color-primary-foreground: #ffffff;
  --color-secondary: #FDE8D8;
  --color-secondary-foreground: #F26522;
  --color-coral: #F4845F;
  --color-coral-foreground: #ffffff;
  --color-muted: #EDE8E2;
  --color-muted-foreground: #8C8782;
  --color-success: #22C55E;
  --color-success-foreground: #ffffff;
  --color-card: #FFFFFF;
  --color-card-foreground: #1A1A1A;
  --color-surface: #F7F3EE;

  /* DO NOT REMOVE: these radius variables are required by the theme editor. */
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-xl: 32px;

  /* DONT CHANGE OR REMOVE THIS VARIABLE */
  --radius: var(--radius-sm);

  /* DO NOT REMOVE: these font variables are required by the theme editor. */
  /* available fonts: "Inter", "DM Sans", "Nunito", "PT Serif", "Space Grotesk", "IBM Plex Mono", "IBM Plex Sans", "Roboto Slab", "Geist", "Shantell Sans" */
  --font-body: DM Sans;
  --font-headings: DM Sans;

  /* Add and change text sizes as you see fit */
  --text-xs: 11px;
  --text-sm: 13px;
  --text-base: 15px;
  --text-lg: 17px;
  --text-xl: 20px;
  --text-2xl: 24px;
  --text-3xl: 30px;
  --text-4xl: 38px;
  --text-5xl: 52px;
}

import Icon from '@global/Icon';

export const displayName = 'App Logo';
export const shortDescription = 'MusikPro logo mark + wordmark';

export default function AppLogo({ size = 'md', dark = false }) {
  const sizes = {
    sm: { icon: 28, text: 'text-base' },
    md: { icon: 36, text: 'text-xl' },
    lg: { icon: 48, text: 'text-2xl' },
  };
  const s = sizes[size] || sizes.md;
  return (
    <div className="flex items-center gap-2">
      <div
        className="bg-primary rounded-lg flex items-center justify-center flex-shrink-0"
        style={{ width: s.icon, height: s.icon }}
      >
        <Icon i="music-2" size={s.icon * 0.55} className="text-primary-foreground" />
      </div>
      <span className={`font-headings font-bold ${s.text} ${dark ? 'text-foreground' : 'text-foreground'}`}>
        {t('MusikPro')}
      </span>
    </div>
  );
}
